import{_ as e,o as s,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/plugins.md","filePath":"zh-HK/user-guide/settings/plugins.md","lastUpdated":1785467127000}'),n={name:"zh-HK/user-guide/settings/plugins.md"};function o(i,t,p,g,l,d){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h1><p>列出所有已安裝的插件，頁面頭部的徽標會顯示當前加載的 Plugin SDK 版本(如果要對照<a href="./../../dev-guide/">開發手冊</a>開發插件，這個版本號很有用)。</p><h2 id="每個插件的卡片" tabindex="-1">每個插件的卡片 <a class="header-anchor" href="#每個插件的卡片" aria-label="Permalink to &quot;每個插件的卡片&quot;">​</a></h2><p>每個已安裝的插件都有一張卡片，顯示圖示、名稱、版本號、DLL 檔案名以及插件的<strong>總體功能簡介</strong>。</p><p>點擊卡片可以展開，查看它註冊的功能組件，按類型分組（搜尋源、動態選單提供者等）——每個可切換的組件都有自己的<strong>啓用/禁用核取方塊</strong>；標記為必要項的組件會顯示一個鎖形圖示，不能關閉。將滑鼠懸停在各組件上時，會彈出該組件的<strong>詳細功能說明 ToolTip</strong>。</p><p>當某個分組（或整個插件）有 2 個及以上可切換組件時，標題旁會出現一個<strong>全選/全不選</strong>鏈接，點擊即可一次性切換該範圍內的所有核取方塊，不用逐個手動勾選。</p><p>如果插件暴露了自己的配置項(超出簡單啓用/禁用的範疇)，卡片頭部會出現一個<strong>配置</strong>按鈕，點擊會打開該插件自己的設定對話方塊。</p><p>頁面底部有一條提示橫幅，說明部分組件的開關改動需要重啓 SwiftList 才能生效。</p><p>如果沒有安裝任何插件，頁面會顯示一個空狀態提示。</p><p>想看插件自己的<strong>配置</strong>對話方塊實際長什麼樣、能改什麼(比如改一個觸發關鍵詞)，可以參考<a href="./../instant-answers.html">即時答案與關鍵詞功能</a>。</p>',10)])])}const h=e(n,[["render",o]]);export{_ as __pageData,h as default};
